<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/accounting_documents.php';
try{accountingDocumentRequireFinance($pdo);}catch(DomainException){http_response_code(403);exit('Přístup má pouze Hospodář a platby.');}
header('Cache-Control: no-store, private');header('Referrer-Policy: no-referrer');
function adH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$error='';$id=(int)($_GET['id']??0);$source=null;
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 if(!csrf_verify((string)($_POST['csrf_token']??''))){http_response_code(403);throw new DomainException('Formulář vypršel.');}
 if(($_POST['confirmed']??'')!=='1')throw new DomainException('Potvrďte vědomé provedení změny.');
 $action=(string)($_POST['action']??'');
 if($action==='issuer')accountingDocumentConfigureIssuer($pdo,$_POST);
 elseif($action==='rule')accountingDocumentConfigureRule($pdo,$_POST);
 elseif($action==='series')accountingDocumentConfigureSeries($pdo,$_POST);
 elseif($action==='draft'){$id=accountingDocumentCreateDraft($pdo,$_POST);}
 elseif($action==='issue'){$id=(int)($_POST['id']??0);accountingDocumentIssue($pdo,$id,(string)($_POST['reason']??''));}
 elseif($action==='correction'){
  $lines=[];foreach((array)($_POST['correction_lines']??[]) as $key=>$line){$amount=str_replace(',','.',trim((string)($line['amount']??'')));if($amount==='')continue;if(!preg_match('/^[0-9]{1,9}(?:\.[0-9]{1,2})?$/D',$amount))throw new DomainException('Částka opravy musí být v Kč, nejvýše dvě desetinná místa.');[$whole,$fraction]=array_pad(explode('.',$amount,2),2,'');$lines[]=['line_key'=>$key,'quantity'=>$line['quantity']??0,'amount_minor'=>(int)$whole*100+(int)str_pad($fraction,2,'0')];}
  $id=accountingDocumentCreateCorrection($pdo,(int)($_POST['id']??0),$lines,(string)($_POST['request_key']??''),(string)($_POST['reason']??''));
 }
 elseif($action==='void'){$id=(int)($_POST['id']??0);accountingDocumentVoidDraft($pdo,$id,(string)($_POST['reason']??''));}
 elseif($action==='revise'){$id=(int)($_POST['id']??0);accountingDocumentReviseParties($pdo,$id,(array)($_POST['buyer']??[]),(array)($_POST['payer']??[]),(string)($_POST['reason']??''));}
 else throw new DomainException('Neplatná operace.');
 header('Location: accounting_documents_admin.php'.($id>0?'?id='.$id:''),true,303);exit;
}catch(InvalidArgumentException|DomainException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Accounting document operation failed: '.get_class($e));$error='Operace se nezdařila. Přidělené číslo zůstává stejné; obnovte přehled a případně opakujte vydání.';}
$row=null;if($id>0)try{$row=accountingDocumentGet($pdo,$id);}catch(DomainException $e){$error=$e->getMessage();}
if($row&&isset($_GET['preview'])){header('Content-Type: text/html; charset=utf-8');echo accountingDocumentHtml($row,app_csp_nonce());exit;}
if(isset($_GET['source_type']))try{$source=accountingDocumentSource($pdo,(string)$_GET['source_type'],(int)($_GET['source_id']??0));}catch(Throwable $e){$error=$e instanceof DomainException||$e instanceof InvalidArgumentException?$e->getMessage():'Případ nelze načíst.';}
$issuers=$pdo->query('SELECT * FROM accounting_issuer_versions ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);$rules=$pdo->query('SELECT * FROM accounting_rules ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);$series=$pdo->query('SELECT * FROM accounting_document_series ORDER BY series_year DESC,kind')->fetchAll(PDO::FETCH_ASSOC);$docs=$pdo->query('SELECT id,kind,number,status,total_minor,currency,source_type,source_id FROM accounting_documents ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
function adCsrf():void{echo '<input type="hidden" name="csrf_token" value="'.adH(csrf_token()).'">';}
function adConfirm():void{echo '<p><label>Důvod / podklad <input name="reason" required maxlength="1000"></label></p><p><label><input type="checkbox" name="confirmed" value="1" required> Potvrzuji uvedené údaje a provedení změny.</label></p>';}
?><!doctype html><html lang="cs"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Účetní doklady</title><?php require_once __DIR__.'/includes/ui_shell.php';appUiAssets();?><style nonce="<?=adH(app_csp_nonce())?>">body{font:16px system-ui;margin:2rem auto;max-width:1120px;padding:0 1rem;color:#192d40}label{display:inline-block;margin:.35rem}input,select,button{font:inherit;padding:.4rem}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ccd4db;padding:.6rem}.error{background:#ffe2e2;padding:1rem}details{margin:1rem 0;padding:1rem;border:1px solid #ccd4db}fieldset{margin:1rem 0}iframe{width:100%;height:650px;border:1px solid #ccd4db}</style></head><body><?php require __DIR__.'/hlavicka.php';?>
<p><a href="club_finance_admin.php">Hospodář a platby</a> · <a href="accounting_documents_admin.php">Přehled dokladů</a></p><h1>Účetní doklady</h1><p>Neplátce DPH. Doklad nemění pohledávku, platbu, členství ani původní variabilní symbol. Účetní členění a vystavovatele nejprve výslovně schvalte podle podkladu účetní.</p>
<?php if($error!==''):?><p class="error"><?=adH($error)?></p><?php endif;?>
<?php if($row):$snapshot=json_decode($row['snapshot_json'],true,512,JSON_THROW_ON_ERROR);?><h2>Doklad #<?=adH($id)?> · <?=adH($row['number']??'koncept')?> · <?=adH($row['status'])?></h2><iframe title="Náhled účetního dokladu" src="?id=<?=adH($id)?>&amp;preview=1"></iframe>
<?php if($row['status']==='issued'):?><p><a href="accounting_document_download.php?id=<?=adH($id)?>">Stáhnout vydané PDF</a></p><?php elseif($row['status']!=='void'):?><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="issue"><input type="hidden" name="id" value="<?=adH($id)?>"><?php adConfirm();?><button>Vydat / opakovat vydání stejného dokladu</button></form><?php endif;?>
<?php if($row['status']==='issued'&&in_array($row['kind'],['invoice','contribution_confirmation'],true)):?><details><summary>Částečná nebo úplná oprava vydaného dokladu</summary><p>Vyplňte kladnou částku pouze u opravovaných položek. Množství 0 znamená cenovou slevu. Peníze ani sklad se tím nemění. Koncept opravy rezervuje částku proti dalším souběžným opravám.</p><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="correction"><input type="hidden" name="id" value="<?=adH($id)?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(20))?>"><table><tr><th>Položka</th><th>Opravované množství</th><th>Částka opravy v Kč</th></tr><?php foreach($snapshot['lines'] as $line):if($line['amount_minor']<=0)continue;?><tr><td><?=adH($line['label'])?></td><td><input name="correction_lines[<?=adH($line['line_key'])?>][quantity]" type="number" min="0" max="<?=adH($line['quantity'])?>" value="0"></td><td><input name="correction_lines[<?=adH($line['line_key'])?>][amount]" inputmode="decimal"></td></tr><?php endforeach;?></table><?php adConfirm();?><button>Připravit opravu bez čísla</button></form></details><?php endif;?>
<?php if($row['status']==='draft'):?><details><summary>Zrušit nepoužitý koncept bez čísla</summary><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="void"><input type="hidden" name="id" value="<?=adH($id)?>"><?php adConfirm();?><button>Zrušit koncept a uvolnit rezervovanou opravu</button></form></details><?php endif;?>
<?php if($row['status']==='draft'&&$row['kind']!=='correction'):?><p>Pokud se změnil obchodní případ, znovu jej načtěte níže, ověřte všechny položky a vytvořte nový náhled. Přestaví se tentýž koncept bez čísla a změna zůstane v historii.</p><details><summary>Opravit odběratele nebo uvedeného plátce v konceptu</summary><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="revise"><input type="hidden" name="id" value="<?=adH($id)?>"><?php foreach(['buyer'=>'Odběratel','payer'=>'Uvedený plátce (volitelné)'] as $p=>$title):?><fieldset><legend><?=adH($title)?></legend><?php foreach(['name'=>'Jméno / název','address'=>'Adresa','registration_id'=>'IČ (volitelné)'] as $key=>$label):?><label><?=adH($label)?> <input name="<?=adH($p)?>[<?=adH($key)?>]" value="<?=adH($snapshot[$p][$key]??'')?>"></label><?php endforeach;?></fieldset><?php endforeach;adConfirm();?><button>Uložit opravu konceptu</button></form></details><?php endif;endif;?>
<h2>Připravit doklad</h2><form method="get"><label>Zdroj <select name="source_type"><option value="order">Objednávka</option><option value="member_charge">Členský předpis</option><option value="movement">Pokladní pohyb</option></select></label><label>ID <input type="number" name="source_id" min="1" required></label><button>Načíst případ a položky</button></form>
<?php if($source):?><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="draft"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(20))?>"><input type="hidden" name="source_type" value="<?=adH($source['source_type'])?>"><input type="hidden" name="source_id" value="<?=adH($source['source_id'])?>"><p>Případ <?=adH($source['reference'])?>, <?=adH(number_format($source['total_minor']/100,2,',',' '))?> Kč</p><label>Doklad <select name="kind"><option value="invoice">Faktura</option><option value="contribution_confirmation">Doklad k členskému příspěvku</option><option value="cash_receipt">Příjmový pokladní doklad</option><option value="cash_disbursement">Výdajový pokladní doklad</option></select></label><label>Datum <input type="date" name="effective_on" value="<?=date('Y-m-d')?>" required></label><label>Splatnost (povinná u faktury) <input type="date" name="due_on" value="<?=adH($source['due_on_suggestion']??'')?>"></label><label>Vystavovatel <select name="issuer_id" required><option value="">Vyberte schválenou verzi</option><?php foreach($issuers as $issuer):$i=json_decode($issuer['snapshot_json'],true);?><option value="<?=adH($issuer['id'])?>"><?=adH('#'.$issuer['id'].' '.$i['name'])?></option><?php endforeach;?></select></label>
<?php foreach(['buyer'=>'Odběratel','payer'=>'Uvedený plátce (volitelné)'] as $p=>$title):?><fieldset><legend><?=adH($title)?></legend><label>Jméno / název <input name="<?=adH($p)?>[name]" value="<?=adH($p==='buyer'?$source['buyer_suggestion']:'')?>" <?=$p==='buyer'?'required':''?> maxlength="200"></label><label>Adresa <input name="<?=adH($p)?>[address]" <?=$p==='buyer'?'required':''?> maxlength="500"></label><label>IČ (volitelné) <input name="<?=adH($p)?>[registration_id]" maxlength="40"></label></fieldset><?php endforeach;?>
<table><tr><th>Položka / účastník</th><th>Částka</th><th>Schválené členění</th></tr><?php foreach($source['lines'] as $line):?><tr><td><?=adH($line['label'])?><br><?=adH($line['beneficiary']['name']??'')?></td><td><?=adH(number_format($line['amount_minor']/100,2,',',' '))?> Kč</td><td><select name="line_rules[<?=adH($line['line_key'])?>]" required><option value="">Vyberte členění</option><?php foreach($rules as $rule):if($rule['source_type']!==$source['source_type'])continue;?><option value="<?=adH($rule['id'])?>"><?=adH($rule['title'].' / '.$rule['category_code'].' / '.$rule['activity'].' / '.$rule['document_kind'])?></option><?php endforeach;?></select></td></tr><?php endforeach;?></table><?php adConfirm();?><button>Vytvořit koncept a náhled bez čísla</button></form><?php endif;?>
<h2>Poslední doklady</h2><table><tr><th>Číslo</th><th>Druh / případ</th><th>Stav</th><th>Částka</th></tr><?php foreach($docs as $d):?><tr><td><a href="?id=<?=adH($d['id'])?>"><?=adH($d['number']??'Koncept #'.$d['id'])?></a></td><td><?=adH($d['kind'].' · '.$d['source_type'].' #'.$d['source_id'])?></td><td><?=adH($d['status'])?></td><td><?=adH(number_format($d['total_minor']/100,2,',',' '))?> <?=adH($d['currency'])?></td></tr><?php endforeach;?></table>
<details><summary>Schválit novou verzi vystavovatele</summary><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="issuer"><input type="hidden" name="vat_payer" value="0"><?php foreach(['name'=>'Název','address'=>'Úplná adresa','registration_id'=>'IČ','bank_account'=>'Účet (volitelné)','approval_evidence'=>'Podklad schválení (účetní, datum, odkaz na uložený podklad)'] as $key=>$label):?><label><?=adH($label)?> <input name="<?=adH($key)?>" <?=$key!=='bank_account'?'required':''?>></label><?php endforeach;adConfirm();?><button>Uložit schválenou verzi</button></form></details>
<details><summary>Schválit nové účetní členění a pravidlo vydání</summary><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="rule"><label>Zdroj <select name="source_type"><option value="order">Objednávka</option><option value="member_charge">Členský předpis</option><option value="movement">Pokladní pohyb</option></select></label><label>Doklad <select name="document_kind"><option value="invoice">Faktura</option><option value="contribution_confirmation">Doklad k členskému příspěvku</option><option value="cash_receipt">Příjmový pokladní doklad</option><option value="cash_disbursement">Výdajový pokladní doklad</option></select></label><?php foreach(['title'=>'Název pravidla','category_code'=>'Účetní členění','activity'=>'Činnost / středisko','approval_evidence'=>'Podklad schválení účetní'] as $key=>$label):?><label><?=adH($label)?> <input name="<?=adH($key)?>" required></label><?php endforeach;?><label>Platí od <input type="date" name="valid_from" required value="<?=date('Y-m-d')?>"></label><?php adConfirm();?><button>Uložit nové pravidlo</button></form></details>
<details><summary>Nová číselná řada dokladů (samostatná od VS)</summary><p>Existující řadu nelze přepsat ani snížit. Výchozí číslo musí navazovat na schválený přechod ze staré evidence.</p><form method="post"><?php adCsrf();?><input type="hidden" name="action" value="series"><label>Druh <select name="kind"><option value="invoice">Faktury</option><option value="contribution_confirmation">Příspěvky</option><option value="correction">Opravy</option><option value="cash_receipt">PPD</option><option value="cash_disbursement">VPD</option></select></label><label>Rok <input name="series_year" type="number" value="<?=date('Y')?>" min="2000" max="2200" required></label><label>Předpona <input name="prefix" pattern="[A-Z0-9-]+" maxlength="20" required></label><label>První číslo <input name="next_number" type="number" min="1" max="99999999" required></label><?php adConfirm();?><button>Založit řadu</button></form><ul><?php foreach($series as $s):?><li><?=adH($s['kind'].' '.$s['prefix'].'-'.$s['series_year'].' · další '.$s['next_number'])?></li><?php endforeach;?></ul></details>
